    /// <summary>
    /// CoC
    /// </summary>
    /// <param name = "_salesLine">_salesLine</param>
    /// <param name = "_inventDim">_inventDim</param>
    /// <returns>Result</returns>
    boolean salesLine_validateWrite(SalesLine _salesLine, InventDim _inventDim)
    {
        FormRun     fr  = FormDataUtil::getFormDataSource(_salesLine).formRun();
        boolean     ret = next salesLine_validateWrite(_salesLine, _inventDim);

        // MPJ-21310
        if(ret)
        {
            METSalesLine metSalesLine = fr.dataHelper().FindDataSource(formDataSourceStr(SalesTable, METSalesLine)).cursor(); 
            ret = METSalesItemSubstitution::runSalesLineCreationFromForm(
                _salesLine,
                metSalesLine,
                _inventDim);
        }
    
        return ret;
    }

/// <summary>
/// CoC
/// </summary>
/// <returns>Result</returns>
public boolean useAlternativeItem()
{
    boolean ret = next useAlternativeItem();
    
    // MPJ-21310
    if(CustParameters::find().METSubstitutionEnabled)
    {
        ret = false;
    }
    return ret;
}
